using System.Text.Json;
using SimplePZMapmaker.Core;
public static class StreetEnsembleTests {
 public static IEnumerable<(string,Action)> Cases(){
  yield return ("street ensemble preview deterministic bounded and atomic",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var before=JsonSerializer.Serialize(p);var o=new StreetEnsembleOptions{X=20,Y=20,Width=100,Height=90,Seed=9};var a=StreetEnsembles.Create(p,o,Resources());var b=StreetEnsembles.Create(p,o,Resources());if(JsonSerializer.Serialize(a)!=JsonSerializer.Serialize(b)||JsonSerializer.Serialize(p)!=before)throw new Exception("Preview changed source or seed");if(a.Buildings.Count!=1||a.Surfaces.All(s=>s.Kind!="parking")||a.Decorations.Count==0||a.AccessPaths.Count!=2)throw new Exception("Ensemble lacks coherent parcel features");var applied=StreetEnsembles.Apply(p,a);ProjectValidator.Validate(applied);if(applied.Buildings.Count!=1||JsonSerializer.Serialize(p)!=before)throw new Exception("Apply not atomic");});
  yield return ("street ensemble complete prop footprints and walk gates stay clear",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var plan=StreetEnsembles.Create(p,new(){X=20,Y=20,Width=100,Height=90},Resources());var occupied=new HashSet<(int,int)>();foreach(var d in plan.Decorations)foreach(var c in d.Parts)if(!occupied.Add((d.X+c.Dx,d.Y+c.Dy)))throw new Exception("Props overlap");if(plan.AccessPaths.SelectMany(a=>a).Any(a=>occupied.Contains((a.X,a.Y))))throw new Exception("Fence or furniture blocks pedestrian access");});
  yield return ("street ensemble stale proposals water and occupied areas reject without mutation",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var plan=StreetEnsembles.Create(p,new(){X=20,Y=20,Width=100,Height=90},Resources());p.Terrain[0]=Terrain.Water;var before=JsonSerializer.Serialize(p);Reject(()=>StreetEnsembles.Apply(p,plan));if(JsonSerializer.Serialize(p)!=before)throw new Exception("Stale apply mutated source");var q=MapGenerator.Generate(new(){Kind="blank"});q.Terrain[35*q.Width+26]=Terrain.Water;Reject(()=>StreetEnsembles.Create(q,new(){X=20,Y=20,Width=100,Height=90},Resources()));});
  yield return ("all street presets retain recessed entrance paths and actual native lights",()=>{foreach(var preset in new[]{"residential","courtyard","garden"}){var p=MapGenerator.Generate(new(){Kind="blank"});var light=new StaticModelPlacement{ModelId="Base.FloorLamp",Profile="light",Light=new()};var plan=StreetEnsembles.Create(p,new(){X=20,Y=20,Width=100,Height=90,Preset=preset},Resources(),light);if(plan.StaticModels.Count!=2||plan.StaticModels.Any(m=>m.Profile!="light"||m.Light is null))throw new Exception("Native lights lost behind fence props");var result=StreetEnsembles.Apply(p,plan);ProjectValidator.Validate(result);}});
 }
 static List<EnsembleResource> Resources()=>[new("fence-n","fencing_01_0",[new(0,0,"fencing_01_0",2)]),new("fence-w","fencing_01_1",[new(0,0,"fencing_01_1",4)]),new("greenery","vegetation_ornamental_01_0",[new(0,0,"vegetation_ornamental_01_0")]),new("bench","furniture_seating_outdoor_01_0",[new(0,0,"furniture_seating_outdoor_01_0",1),new(1,0,"furniture_seating_outdoor_01_1",1)])];
 static void Reject(Action a){try{a();}catch(ArgumentException){return;}throw new Exception("Invalid proposal accepted");}
}
